'use strict';
const D=JSON.parse(document.getElementById('review-data').textContent),$=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={aplicat:'Aplicat',aplicat_selectiv:'Aplicat selectiv',aplicat_partial:'Aplicat parțial',propus:'Propus',plan_pregatit:'Plan pregătit',propus_neexecutat:'Propus, neexecutat',acoperit_documentar:'Acoperit documentar',partial:'Parțial',limita_explicitata:'Limită explicitată',livrat:'Livrat'};
const label=s=>labels[s]||s.replaceAll('_',' '),tag=s=>'<span class="tag">'+esc(label(s))+'</span>';
const block=(title,body)=>'<div class="label">'+esc(title)+'</div><p>'+esc(body)+'</p>';
const evidence=a=>'<div class="links">'+(a||[]).map(x=>'<a href="../'+esc(x)+'">'+esc(x.split('/').at(-1))+'</a>').join('')+'</div>';
const ids=(a)=>'<div class="links">'+(a||[]).map(x=>'<a href="#'+esc(x)+'">'+esc(x)+'</a>').join('')+'</div>';
const normalize=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function selectTab(tab){document.querySelectorAll('.panel').forEach(x=>x.hidden=x.id!=='panel-'+tab);document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.tab===tab)));}
document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{selectTab(b.dataset.tab);history.replaceState(null,'','#'+b.dataset.tab);}));
function renderRequests(){const term=normalize($('#request-search').value),items=D.requests.filter(x=>normalize(JSON.stringify(x)).includes(term));$('#request-count').textContent=items.length+' / '+D.requests.length+' solicitări';$('#requests-list').innerHTML=items.map(q=>'<details id="'+q.id+'"><summary>'+esc(q.id+' · '+q.topic)+'</summary><div class="detail">'+block('Solicitarea originală',q.question)+block('Ce funcționează în răspuns',q.strength)+block('Ce merită completat',q.gap)+block('Îmbunătățire',q.improvement)+'<div class="label">Criterii de acceptare</div><p class="small">Evaluarea se bazează pe răspunsul original păstrat mai jos. Legăturile de context nu sunt o reverificare factuală a fiecărei subcerințe.</p>'+D.requirements.filter(r=>r.requestId===q.id).map(r=>'<div class="criterion" id="'+r.id+'"><b>'+esc(r.id+' · '+r.requirement)+'</b> '+tag(r.assessment)+'<p>'+esc(r.acceptance)+'</p><p class="small">'+esc(r.evidenceLevel)+'</p></div>').join('')+'<div class="label">Artefacte de context ale solicitării</div>'+evidence(q.evidence)+ids([...q.methods,...q.experiments])+'<details class="answer"><summary>Răspunsul original, păstrat pentru comparație</summary><div class="detail">'+q.answers.map(a=>'<pre class="original">'+esc(a.text)+'</pre>').join('')+'</div></details></div></details>').join('');}
$('#request-search').addEventListener('input',renderRequests);renderRequests();
function renderMethods(){const s=$('#method-state').value,items=D.methods.filter(m=>s==='all'||(s==='done'?m.status.startsWith('aplicat'):!m.status.startsWith('aplicat')));$('#method-count').textContent=items.length+' / '+D.methods.length+' metode';$('#methods-list').innerHTML=items.map(m=>'<article class="card" id="'+m.id+'"><div class="tags">'+tag(m.priority)+tag(m.status)+tag('efort: '+m.effort)+'</div><h3>'+esc(m.id+' · '+m.title)+'</h3><p>'+esc(m.method)+'</p>'+block('Criteriu de succes',m.success)+'<a href="'+esc(m.artifact)+'">Artefact / plan</a>'+ids(m.sources)+'</article>').join('');}
$('#method-state').addEventListener('change',renderMethods);renderMethods();
$('#metrics-list').innerHTML=D.indicators.metrics.map(m=>'<article class="card" id="'+m.id+'"><h3>'+esc(m.title)+'</h3><div class="metric">'+m.numerator+' / '+m.denominator+' <small>· '+m.percent.toLocaleString('ro-RO')+'%</small></div><div class="bar" aria-hidden="true"><span style="width:'+m.percent+'%"></span></div><p>'+esc(m.meaning)+'</p><p class="small">'+esc(m.limit)+'</p>'+evidence([m.source])+'</article>').join('');
$('#maturity-list').innerHTML=D.indicators.maturity.map(m=>'<article class="maturity"><div><b>'+esc(m.stage)+'</b><div>'+tag(m.state)+'</div></div><div><p>'+esc(m.evidence)+'</p><p class="small">'+esc(m.limit)+'</p></div></article>').join('');
$('#future-list').innerHTML=D.indicators.futureMetrics.map(m=>'<article class="card"><h3>'+esc(m.id+' · '+m.title)+'</h3>'+block('Definiție',m.formula)+block('Stare',m.status)+'<p class="small">'+esc(m.limit)+'</p></article>').join('');
$('#requirement-states').innerHTML=Object.entries(D.indicators.conversation.requirementStates).map(([k,v])=>tag(label(k)+': '+v)).join(' ');
$('#queue-group').innerHTML=D.queue.groups.map(g=>'<option value="'+g.id+'">'+esc(g.title)+' ('+g.count+')</option>').join('');
let queuePage=0;const PAGE_SIZE=20;
function renderQueue(){const g=D.queue.groups.find(g=>g.id===$('#queue-group').value),term=normalize($('#queue-search').value),items=g.items.filter(x=>normalize(JSON.stringify(x)).includes(term)),pages=Math.max(1,Math.ceil(items.length/PAGE_SIZE));queuePage=Math.min(queuePage,pages-1);$('#queue-note').innerHTML='<p>'+tag(g.priority)+' '+esc(g.next)+'</p><p class="small">Regulă: '+esc(g.rule)+' · '+g.count+(g.denominator?' / '+g.denominator:'')+' '+esc(g.unit)+'</p>';$('#queue-count').textContent=items.length+' rezultate în această grupă';$('#queue-list').innerHTML=items.slice(queuePage*PAGE_SIZE,(queuePage+1)*PAGE_SIZE).map(x=>'<tr><td>'+(x.href?'<a href="'+esc(x.href)+'">'+esc(x.id)+'</a>':esc(x.id))+'</td><td>'+esc(x.name)+'</td><td>'+esc(x.scope||x.source)+(x.line?':'+x.line:'')+'</td></tr>').join('')||'<tr><td colspan="3">Niciun rezultat.</td></tr>';$('#queue-page').textContent=(queuePage+1)+' / '+pages;$('#prev-page').disabled=queuePage===0;$('#next-page').disabled=queuePage===pages-1;}
$('#queue-group').addEventListener('change',()=>{queuePage=0;renderQueue()});$('#queue-search').addEventListener('input',()=>{queuePage=0;renderQueue()});$('#prev-page').addEventListener('click',()=>{queuePage--;renderQueue()});$('#next-page').addEventListener('click',()=>{queuePage++;renderQueue()});renderQueue();
$('#experiments-list').innerHTML=D.experiments.map(e=>'<details id="'+e.id+'"><summary>'+esc(e.id+' · '+e.title)+'</summary><div class="detail"><div class="tags">'+tag(e.priority)+tag(e.status)+'</div>'+block('Ipoteză',e.hypothesis)+block('Necesită',e.requires)+'<div class="label">Procedură</div><ol>'+e.steps.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ol>'+block('Acceptare',e.acceptance)+block('Măsurători',e.metrics.join(' · '))+block('Limită',e.limit)+ids([...e.methods,...e.sources])+'</div></details>').join('');
$('#claims-list').innerHTML=D.claims.map(c=>'<details id="'+c.id+'"><summary>'+esc(c.id+' · '+c.claim)+'</summary><div class="detail">'+tag(c.status)+block('Aplicabilitate',c.appliesTo)+block('Limită',c.limit)+block('Ce poate schimba concluzia',c.nextEvidence)+evidence(c.evidence)+'<div class="links">'+c.urls.map(u=>'<a href="'+esc(u)+'">Sursă oficială / primară</a>').join('')+'</div>'+ids(c.requestIds)+'</div></details>').join('');
$('#evolution-list').innerHTML=D.evolution.map(v=>'<article class="card" id="'+v.id+'"><div>'+tag(v.type)+'</div>'+block('Anterior',v.before)+block('Acum',v.now)+block('Motiv',v.why)+ids([...v.requestIds,...v.claimIds])+evidence(v.evidence)+'</article>').join('');
$('#sources-list').innerHTML=D.sources.map(s=>'<article class="card" id="'+s.id+'"><h3><a href="'+esc(s.url)+'">'+esc(s.title)+'</a></h3><p>'+esc(s.use)+'</p><p class="small">'+esc(s.limit)+' · Verificat '+esc(s.checkedAt)+'</p></article>').join('');
function route(){const id=decodeURIComponent(location.hash.slice(1));if(!id)return;const known=['requests','methods','metrics','queue','experiments','claims','sources'];if(known.includes(id)){selectTab(id);return;}let tab=/^S\d/.test(id)?'requests':/^M\d/.test(id)?'methods':/^K\d/.test(id)?'metrics':/^E\d/.test(id)?'experiments':/^[AV]\d/.test(id)?'claims':D.sources.some(x=>x.id===id)?'sources':null;if(!tab)return;if(tab==='requests'&&$('#request-search').value){$('#request-search').value='';renderRequests();}if(tab==='methods'&&$('#method-state').value!=='all'){$('#method-state').value='all';renderMethods();}selectTab(tab);const el=document.getElementById(id);if(el){let parent=el;while(parent){if(parent.tagName==='DETAILS')parent.open=true;parent=parent.parentElement;}requestAnimationFrame(()=>el.scrollIntoView({block:'start'}));}}
addEventListener('hashchange',route);route();
